import {useCallback, useEffect, useRef, useState} from 'react'

import {ActionList, ActionMenu, Label, Textarea} from '@primer/react'
import {Dialog} from '@primer/react/experimental'

import {isFeatureEnabled} from '@github-ui/feature-flags'
import {testIdProps} from '@github-ui/test-id-props'
import {AT_COPILOT_VALUE} from '@github-ui/filter-core/providers'
import {INIT_EVENT, END_EVENT} from '@github-ui/copilot-summary-banner/constants'

import {DEFAULT_SUMMARY_PROMPT} from './prompts'

export interface CopilotMarkdownToolbarButtonProps {
  anchorId: string
  userLogin: string | undefined
  pullRequestSummaryEnabled: boolean
  pullRequestSummaryPromptEditorEnabled: boolean
  copilotCodeReviewHintEnabled: boolean
}

export function CopilotMarkdownToolbarButton({
  anchorId,
  pullRequestSummaryEnabled,
  pullRequestSummaryPromptEditorEnabled,
  copilotCodeReviewHintEnabled,
}: CopilotMarkdownToolbarButtonProps) {
  const [menuOpen, setMenuOpen] = useState<boolean>(false)
  const [summaryDisabled, setSummaryDisabled] = useState<boolean>(false)
  const [promptEditorOpen, setPromptEditorOpen] = useState<boolean>(false)
  const [customPrompt, setCustomPrompt] = useState<string>(DEFAULT_SUMMARY_PROMPT)
  const [pendingAction, setPendingAction] = useState<string | null>(null)
  const boxRef = useRef<HTMLDivElement>(null)
  const buttonRef = useRef<HTMLElement | null>(null)

  const splitActionsEnabled = isFeatureEnabled('copilot_split_actions_enabled')

  const handleCopilotMention = useCallback(() => {
    const form = boxRef.current?.closest('form')
    if (!form) return

    const textarea = form.querySelector<HTMLTextAreaElement>('.js-comment-field')
    if (!textarea) return

    // Current cursor position
    const start = textarea.selectionStart ?? 0
    const end = textarea.selectionEnd ?? 0
    const currentValue = textarea.value

    // Determine spacing needs around @copilot mention
    const charBefore = start > 0 ? currentValue[start - 1] : ''
    const charAfter = end < currentValue.length ? currentValue[end] : ''

    // Add leading space if previous character exists and is not whitespace
    const needsLeadingSpace = charBefore ? !/\s/.test(charBefore) : false
    // Add trailing space unless next character is already whitespace
    const hasTrailingSpace = charAfter ? /\s/.test(charAfter) : false

    // Build the mention text with appropriate spacing
    const leadingSpace = needsLeadingSpace ? ' ' : ''
    const trailingSpace = hasTrailingSpace ? '' : ' '
    const mentionText = `${leadingSpace}${AT_COPILOT_VALUE}${trailingSpace}`

    // Insert the mention into the textarea
    const newValue = currentValue.slice(0, start) + mentionText + currentValue.slice(end)
    textarea.value = newValue

    // set the new cursor position
    const newCursorPos = start + mentionText.length
    textarea.setSelectionRange(newCursorPos, newCursorPos)
    textarea.focus()

    // Dispatch both input and change events to trigger form validation
    textarea.dispatchEvent(new Event('input', {bubbles: true}))
    textarea.dispatchEvent(new Event('change', {bubbles: true}))
  }, [])

  useEffect(() => {
    if (typeof document === 'undefined') {
      return
    }

    buttonRef.current = document.getElementById(anchorId)
    if (buttonRef.current === null) {
      return
    }

    const handleButtonClick = () => {
      if (copilotCodeReviewHintEnabled) {
        handleCopilotMention()
      } else {
        setMenuOpen(open => !open)
      }
    }

    const button = buttonRef.current
    button.setAttribute('aria-expanded', menuOpen.toString())
    button.addEventListener('click', handleButtonClick)
    return () => {
      button.removeEventListener('click', handleButtonClick)
    }
  }, [anchorId, menuOpen, copilotCodeReviewHintEnabled, handleCopilotMention])

  const executeCopilotSummary = useCallback(
    (action: string | null, useCustomPrompt: boolean = false) => {
      const form = boxRef.current!.closest('form')
      if (!form || !action) return

      setSummaryDisabled(true)

      // Create the custom event with the action and conditionally include custom prompt
      const summaryTrigger = new CustomEvent(INIT_EVENT, {
        bubbles: true,
        detail: {action, ...(useCustomPrompt && {customPrompt})},
      })
      const reenableSummary = () => {
        setSummaryDisabled(false)
      }

      form.dispatchEvent(summaryTrigger)
      form.addEventListener(END_EVENT, reenableSummary, {once: true})
    },
    [boxRef, customPrompt],
  )

  const triggerCopilotSummary = useCallback(
    (event: React.UIEvent<HTMLElement>) => {
      const action = event.currentTarget.getAttribute('data-copilot-action')
      setMenuOpen(false)
      executeCopilotSummary(action)
    },
    [setMenuOpen, executeCopilotSummary],
  )

  const openPromptEditor = useCallback(
    (event: React.UIEvent<HTMLElement>) => {
      const action = event.currentTarget.getAttribute('data-copilot-action')
      setPendingAction(action)
      setPromptEditorOpen(true)
      setMenuOpen(false)
    },
    [setPendingAction, setPromptEditorOpen, setMenuOpen],
  )

  const handlePromptSubmit = useCallback(() => {
    setPromptEditorOpen(false)
    executeCopilotSummary(pendingAction, true)
    setPendingAction(null)
  }, [setPromptEditorOpen, executeCopilotSummary, pendingAction, setPendingAction])

  const handlePromptCancel = useCallback(() => {
    setPromptEditorOpen(false)
    setPendingAction(null)
  }, [setPromptEditorOpen, setPendingAction])

  const handlePromptChange = useCallback(
    (event: React.ChangeEvent<HTMLTextAreaElement>) => {
      setCustomPrompt(event.target.value)
    },
    [setCustomPrompt],
  )

  const handlePromptReset = useCallback(() => {
    setCustomPrompt(DEFAULT_SUMMARY_PROMPT)
  }, [setCustomPrompt])

  return (
    <div ref={boxRef} {...testIdProps('copilot-md-actions')}>
      <ActionMenu open={menuOpen} onOpenChange={setMenuOpen} anchorRef={buttonRef}>
        <ActionMenu.Overlay width="medium">
          <ActionList>
            {(pullRequestSummaryEnabled || splitActionsEnabled) && (
              <ActionList.Group>
                <ActionList.GroupHeading>Generate</ActionList.GroupHeading>
                {pullRequestSummaryEnabled && (
                  <ActionList.Item
                    onSelect={triggerCopilotSummary}
                    disabled={summaryDisabled}
                    data-copilot-action={splitActionsEnabled ? 'summary' : 'all'}
                    {...testIdProps('copilot-pr-summary-btn')}
                  >
                    Summary
                    <ActionList.Description variant="block">
                      Generate a summary of the changes in this pull request.
                    </ActionList.Description>
                  </ActionList.Item>
                )}
                {splitActionsEnabled && (
                  <ActionList.Item
                    onSelect={triggerCopilotSummary}
                    disabled={summaryDisabled}
                    data-copilot-action="outline"
                    {...testIdProps('copilot-pr-outline-btn')}
                  >
                    Outline
                    <ActionList.Description variant="block">
                      Generate a list of the most important changed files in this pull request.
                    </ActionList.Description>
                  </ActionList.Item>
                )}
                {pullRequestSummaryPromptEditorEnabled && (
                  <>
                    <ActionList.Divider />
                    <ActionList.Item onSelect={openPromptEditor} disabled={summaryDisabled} data-copilot-action="all">
                      Edit prompt
                      <ActionList.Description variant="block">
                        Customize the prompt before generating a summary.
                      </ActionList.Description>
                      <ActionList.TrailingVisual>
                        <Label variant="attention">Staff</Label>
                      </ActionList.TrailingVisual>
                    </ActionList.Item>
                  </>
                )}
              </ActionList.Group>
            )}
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>

      {promptEditorOpen && (
        <Dialog
          title={
            <>
              Edit prompt{' '}
              <Label variant="attention" className="ml-1">
                Staff
              </Label>
            </>
          }
          footerButtons={[
            {buttonType: 'default', content: 'Reset', onClick: handlePromptReset},
            {buttonType: 'primary', content: 'Continue', onClick: handlePromptSubmit},
          ]}
          onClose={handlePromptCancel}
          {...testIdProps('copilot-prompt-editor')}
        >
          <Textarea
            value={customPrompt}
            onChange={handlePromptChange}
            rows={12}
            block
            resize="vertical"
            autoFocus
            {...testIdProps('copilot-prompt-textarea')}
          />
        </Dialog>
      )}
    </div>
  )
}
